<?php
namespace Certloom\Infrastructure\Admin;

use Certloom\Application\Issuance\PendingRequestAdminService;
use Certloom\Domain\Issuance\IssuanceRequestState;

if ( ! defined( 'ABSPATH' ) ) { exit; }

final class PendingRequestAdmin {
	const PAGE = 'certloom-pending-requests';
	private $page_hook;
	public function register() { add_action( 'admin_menu', array( $this, 'menu' ), 30 ); add_action( 'admin_enqueue_scripts', array( $this, 'enqueue' ) ); add_filter( 'admin_title', array( $this, 'title' ) ); }
	public function menu() { $this->page_hook = add_submenu_page( null, __( 'Certificate requests', 'certloom' ), __( 'Certificate requests', 'certloom' ), \Ecapla_CertVerify_Permissions::CAP_MANAGE_CREDENTIALS, self::PAGE, array( $this, 'render' ) ); }
	public function enqueue( $hook ) { if ( $hook === $this->page_hook ) { $this->assets(); } }
	public function title( $title ) { $screen = get_current_screen(); return $screen && $screen->id === $this->page_hook ? __( 'Certificate requests', 'certloom' ) . ' ‹ ' . get_bloginfo( 'name' ) . ' — WordPress' : $title; }
	private function assets() {
		wp_enqueue_style( 'certloom-tokens', ECAPLA_CERTVERIFY_URL . 'assets/css/certloom-tokens.css', array(), (string) filemtime( ECAPLA_CERTVERIFY_PATH . 'assets/css/certloom-tokens.css' ) );
		wp_enqueue_style( 'certloom-recipient-account', ECAPLA_CERTVERIFY_URL . 'public/assets/certloom-recipient-account.css', array( 'certloom-tokens' ), (string) filemtime( ECAPLA_CERTVERIFY_PATH . 'public/assets/certloom-recipient-account.css' ) );
		wp_enqueue_style( 'certloom-pending-requests', ECAPLA_CERTVERIFY_URL . 'admin/assets/certloom-pending-requests.css', array( 'certloom-recipient-account' ), (string) filemtime( ECAPLA_CERTVERIFY_PATH . 'admin/assets/certloom-pending-requests.css' ) );
		wp_enqueue_script( 'certloom-pending-requests', ECAPLA_CERTVERIFY_URL . 'admin/assets/certloom-pending-requests.js', array(), (string) filemtime( ECAPLA_CERTVERIFY_PATH . 'admin/assets/certloom-pending-requests.js' ), true );
		wp_enqueue_script( 'certloom-pending-policy', ECAPLA_CERTVERIFY_URL . 'admin/assets/certloom-pending-policy.js', array(), (string) filemtime( ECAPLA_CERTVERIFY_PATH . 'admin/assets/certloom-pending-policy.js' ), true );
	}
